--- accepted/cloud-signin-window.c
+++ qa/current.c
@@ -787,7 +787,7 @@
     static gboolean probing = FALSE;
     if (data && !probing) {
         probing = TRUE;
-        g_timeout_add(500, probe_tick, data);
+        if (!g_getenv("QA_NO_PROBE")) g_timeout_add(500, probe_tick, data);
     }
 }

@@ -970,6 +970,12 @@
      * login page wanders through cookie banners and footer links before it
      * reaches the password field. */
     WebKitSettings *settings = webkit_web_view_get_settings(view);
+    /* QA-only: isolate cache model and UA with the same compiled source. */
+    if (g_getenv("QA_DOCUMENT_VIEWER"))
+        webkit_web_context_set_cache_model(context, WEBKIT_CACHE_MODEL_DOCUMENT_VIEWER);
+    if (g_getenv("QA_DESKTOP_UA"))
+        webkit_settings_set_user_agent(settings, "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/60.5 Safari/605.1.15");
+    g_message("QA engine=%u.%u.%u cache=%d dmabuf=%s ua=%s", webkit_get_major_version(), webkit_get_minor_version(), webkit_get_micro_version(), webkit_web_context_get_cache_model(context), g_getenv("WEBKIT_DISABLE_DMABUF_RENDERER"), webkit_settings_get_user_agent(settings));
     webkit_settings_set_enable_spatial_navigation(settings, TRUE);
     webkit_settings_set_enable_tabs_to_links(settings, TRUE);
